create table if not exists public.pilot_documents (key text primary key, state jsonb not null default '{}'::jsonb, version bigint not null default 0, updated_at timestamptz not null default now());
create table if not exists public.catalog_records (id uuid primary key default gen_random_uuid(), category text not null, record_key text not null, payload jsonb not null, source_hash text, approved_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(category, record_key));
create table if not exists public.catalog_batches (batch_id text primary key, payload jsonb not null, status text not null default 'pending', expires_at timestamptz not null default now() + interval '7 days', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.radar_items (item_key text primary key, payload jsonb not null, source_hash text, summary_input_hash text, updated_at timestamptz not null default now());
create table if not exists public.processing_runs (id uuid primary key default gen_random_uuid(), operation text not null, request_hash text not null, status text not null default 'running', payload jsonb, error text, expires_at timestamptz not null default now() + interval '7 days', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(operation, request_hash));
create table if not exists public.ai_cache (cache_key text primary key, task text not null, model text, result jsonb not null, expires_at timestamptz not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.ai_usage_events (id uuid primary key default gen_random_uuid(), task text not null, model text, input_tokens integer not null default 0, output_tokens integer not null default 0, reasoning_tokens integer not null default 0, cached_tokens integer not null default 0, total_tokens integer not null default 0, cost_usd numeric(18,8) not null default 0, cache_hit boolean not null default false, created_at timestamptz not null default now(), expires_at timestamptz not null default now() + interval '7 days');
create table if not exists public.ai_usage_daily (day date primary key, requests integer not null default 0, total_tokens bigint not null default 0, cost_usd numeric(18,8) not null default 0, updated_at timestamptz not null default now());
create table if not exists public.operation_rate_limits (operation_key text primary key, count integer not null default 0, reset_at timestamptz not null, updated_at timestamptz not null default now());
create index if not exists ai_cache_expires_idx on public.ai_cache(expires_at);
create index if not exists ai_usage_events_created_idx on public.ai_usage_events(created_at desc);
create index if not exists catalog_batches_expires_idx on public.catalog_batches(expires_at);
create index if not exists processing_runs_expires_idx on public.processing_runs(expires_at);
do $$ declare t text; begin foreach t in array array['pilot_documents','catalog_records','catalog_batches','radar_items','processing_runs','ai_cache','ai_usage_events','ai_usage_daily','operation_rate_limits'] loop execute format('alter table public.%I enable row level security', t); end loop; end $$;
create or replace function public.write_pilot_document(p_key text,p_state jsonb,p_expected_version bigint default null) returns table(version bigint) language plpgsql security definer set search_path=public as $$ declare next_version bigint; begin insert into public.pilot_documents(key,state,version) values(p_key,p_state,1) on conflict(key) do update set state=excluded.state,version=pilot_documents.version+1,updated_at=now() where p_expected_version is null or pilot_documents.version=p_expected_version returning pilot_documents.version into next_version; if next_version is null then raise exception 'pilot_document_conflict' using errcode='40001'; end if; return query select next_version; end; $$;
create or replace function public.record_ai_usage(p_task text,p_model text,p_input_tokens integer default 0,p_output_tokens integer default 0,p_reasoning_tokens integer default 0,p_cached_tokens integer default 0,p_total_tokens integer default 0,p_cost_usd numeric default 0,p_cache_hit boolean default false) returns void language plpgsql security definer set search_path=public as $$ begin insert into public.ai_usage_events(task,model,input_tokens,output_tokens,reasoning_tokens,cached_tokens,total_tokens,cost_usd,cache_hit) values(p_task,nullif(p_model,''),greatest(p_input_tokens,0),greatest(p_output_tokens,0),greatest(p_reasoning_tokens,0),greatest(p_cached_tokens,0),greatest(p_total_tokens,0),greatest(p_cost_usd,0),p_cache_hit); insert into public.ai_usage_daily(day,requests,total_tokens,cost_usd) values(current_date,1,greatest(p_total_tokens,0),greatest(p_cost_usd,0)) on conflict(day) do update set requests=ai_usage_daily.requests+1,total_tokens=ai_usage_daily.total_tokens+excluded.total_tokens,cost_usd=ai_usage_daily.cost_usd+excluded.cost_usd,updated_at=now(); end; $$;
create or replace function public.cleanup_expired_pilot_data() returns void language plpgsql security definer set search_path=public as $$ begin delete from public.ai_cache where expires_at<=now(); delete from public.catalog_batches where expires_at<=now() and status<>'committed'; delete from public.processing_runs where expires_at<=now(); delete from public.ai_usage_events where expires_at<=now(); end; $$;
create or replace function public.consume_operation_limit(p_key text,p_limit integer,p_window_seconds integer) returns boolean language plpgsql security definer set search_path=public as $$ declare allowed boolean; begin insert into public.operation_rate_limits(operation_key,count,reset_at) values(p_key,1,now()+make_interval(secs=>p_window_seconds)) on conflict(operation_key) do update set count=case when operation_rate_limits.reset_at<=now() then 1 else operation_rate_limits.count+1 end,reset_at=case when operation_rate_limits.reset_at<=now() then now()+make_interval(secs=>p_window_seconds) else operation_rate_limits.reset_at end,updated_at=now(); select count<=p_limit into allowed from public.operation_rate_limits where operation_key=p_key; return allowed; end; $$;
create or replace function public.claim_processing_run(p_operation text,p_request_hash text) returns setof public.processing_runs language plpgsql security definer set search_path=public as $$ declare claimed public.processing_runs; begin insert into public.processing_runs(operation,request_hash,status) values(p_operation,p_request_hash,'running') on conflict(operation,request_hash) do update set updated_at=now() where processing_runs.status='failed' or processing_runs.expires_at<=now() returning * into claimed; if claimed.id is not null then return next claimed; else return query select * from public.processing_runs where operation=p_operation and request_hash=p_request_hash; end if; end; $$;
revoke all on all tables in schema public from anon, authenticated;
revoke execute on function public.write_pilot_document(text,jsonb,bigint) from public, anon, authenticated;
revoke execute on function public.record_ai_usage(text,text,integer,integer,integer,integer,integer,numeric,boolean) from public, anon, authenticated;
revoke execute on function public.cleanup_expired_pilot_data() from public, anon, authenticated;
revoke execute on function public.consume_operation_limit(text,integer,integer) from public, anon, authenticated;
revoke execute on function public.claim_processing_run(text,text) from public, anon, authenticated;
